package com.vandorlabs.neoforge.programmer;
import com.google.gson.*;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.*;
/** Real connection updates, separated from ordinary torch/solid-side support. */
final class ProgrammerContactChecks {
 private static int checks;
 private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Programmer contacts: "+why);}
 @SuppressWarnings({"unchecked","rawtypes"})private static boolean connected(BlockState state,Direction side){for(var property:state.getProperties())if(property.getName().equals(side.getName())){Object value=state.getValue((Property)property);return value instanceof Boolean flag?flag:value!=WallSide.NONE;}throw new AssertionError("No native connection property");}
 static void run(ServerLevel level,NativeProgrammerBlock block,net.minecraft.server.level.ServerPlayer actor,BlockPos root)throws Exception{var source=JsonParser.parseString(Files.readString(Path.of(System.getenv("VANDOR_PROGRAMMER_CONTACTS_REFERENCE")))).getAsJsonObject();var rows=source.getAsJsonArray("cases");need(rows.size()==384&&source.get("golden").getAsString().equals("dbbc7bd78029ce41ef9c42414202bd0b35de0d09644d7d1afa3fe72a1feb9efc")&&java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(new Gson().toJson(rows).getBytes(java.nio.charset.StandardCharsets.UTF_8))).equals(source.get("golden").getAsString()),"frozen actual Source contact corpus");Block[] neighbors={Blocks.OAK_FENCE,Blocks.NETHER_BRICK_FENCE,Blocks.COBBLESTONE_WALL,Blocks.IRON_BARS,Blocks.GLASS_PANE,Blocks.WHITE_STAINED_GLASS_PANE};level.getChunkAt(root);int profile=0;for(var value:rows){var row=value.getAsJsonObject();int meta=row.get("meta").getAsInt();var side=Direction.from3DDataValue(row.get("side").getAsInt());var state=block.defaultBlockState().setValue(NativeProgrammerBlock.FACING,Direction.from2DDataValue(meta&3)).setValue(NativeProgrammerBlock.PART,meta>>2);level.setBlock(root,state,2);var pos=root.relative(side);var toward=side.getOpposite();var initial=neighbors[row.get("kind").getAsInt()].defaultBlockState();var joined=initial.updateShape(toward,state,level,pos,root);need(connected(joined,toward)==row.get("connected").getAsBoolean(),"actual Source connection profile="+profile+" kind="+row.get("kind")+" meta="+meta);actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.setPos(root.getX()+.5,root.getY(),root.getZ()-2);var held=new net.minecraft.world.item.ItemStack(neighbors[row.get("kind").getAsInt()]);actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,held);var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(root).add(side.getStepX()*.5,0,side.getStepZ()*.5),side,root,false);need(held.useOn(new net.minecraft.world.item.context.UseOnContext(actor,net.minecraft.world.InteractionHand.MAIN_HAND,hit)).consumesAction()&&held.isEmpty(),"actual vanilla neighbor item placement");need(connected(level.getBlockState(pos),toward)==row.get("connected").getAsBoolean(),"actual placement connection matches Source");level.removeBlock(pos,false);need(state.isFaceSturdy(level,root,side)==row.get("solidSupport").getAsBoolean(),"ordinary support remains Source false");var detached=joined.updateShape(toward,Blocks.AIR.defaultBlockState(),level,pos,root);need(!connected(detached,toward),"removal clears connection");profile++;}level.removeBlock(root,false);System.out.println("[vandorlabs][programmer-contacts] PASS SourceCases="+profile+" checks="+checks+" fence/wall/panes/ordinary-support/removal");}
}
